        jdbc.update("INSERT INTO compensation_item (compensation_id, dye_code, batch_no, factor_version, "
                + "potency_factor, base_target_g, compensated_target_g) VALUES (?, ?, ?, ?, ?, ?, ?)",
                targetComp.get("id"), item.get("dye_code"), item.get("batch_no"),
