    @Test
    void controlledFeed_deviationExactlyHalfAllowed_deductsBatchOnly_andWeighingChainFrozen() {
        registerBatch("cf-1", "B-RED-08", "D-RED", "0.8", "100000", FAR_FUTURE);
        scheduleControlled("cf-s", "LCF", "VCF", "R-BASE", 1, "50");
