                        "D-RED", List.of("B-RED-08", 1),
                        "D-YELLOW", List.of("B-YELLOW-001", 1),
                        "D-BLUE", List.of("B-BLUE-001", 1)))));
        assertEquals(422, reapprove.getStatusCode().value());
    }

